package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Loan;

import java.util.Arrays;
import java.util.List;

class LoanMapper {

    Loan toDomain(LoanJpaEntity entity) {
        return Loan.reconstitute(entity.getId(), entity.getBookId(), entity.getMemberId(), entity.getLoanedAt(),
                entity.getDueAt(), entity.getReturnedAt(), toCreditCheck(entity));
    }

    LoanJpaEntity toEntity(Loan loan) {
        CreditCheck creditCheck = loan.getCreditCheck();
        if (creditCheck == null) {
            return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                    loan.getDueAt(), loan.getReturnedAt(), null, null, null, null, null, null);
        }
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                loan.getDueAt(), loan.getReturnedAt(), creditCheck.approved(), creditCheck.score(),
                String.join(",", creditCheck.reasonCodes()), creditCheck.checkedAt(),
                creditCheck.providerName(), creditCheck.providerVersion());
    }

    private CreditCheck toCreditCheck(LoanJpaEntity entity) {
        if (entity.getCreditApproved() == null) {
            return null;
        }
        return new CreditCheck(entity.getCreditApproved(), entity.getCreditScore(), toReasonCodes(entity.getCreditReasonCodes()),
                entity.getCreditCheckedAt(), entity.getCreditProviderName(), entity.getCreditProviderVersion());
    }

    private List<String> toReasonCodes(String joined) {
        if (joined == null || joined.isEmpty()) {
            return List.of();
        }
        return Arrays.asList(joined.split(","));
    }
}

